            break
        valid = True
        for j in range(1, char_len):
            if data[i + j] & 0xC0 != 0x80:
                valid = False
                break
        if not valid:
            break
        char_bytes = data[i:i+char_len]
        if len(result) + len(char_bytes) > max_bytes:
            break
        result.extend(char_bytes)
